from urllib.parse import urlsplit, urlunsplit, parse_qsl


def apply_rewrite_rules(rules, urls):
    """
    Apply the first matching rewrite rule to each URL.

    Returns a list containing rewritten URLs, unchanged URLs, or None for
    blocked URLs.
    """

    def host_matches(host, match_value):
        if not host:
            return False

        host = host.lower()
        match_value = match_value.lower()

        if match_value.startswith("*."):
            base_domain = match_value[2:]
            # Must be a subdomain, not the base domain itself.
            return host.endswith("." + base_domain)

        return host == match_value

    def replace_host(parts, new_host):
        netloc = parts.netloc

        # Preserve user information.
        if "@" in netloc:
            userinfo, hostport = netloc.rsplit("@", 1)
            prefix = userinfo + "@"
        else:
            hostport = netloc
            prefix = ""

        # Preserve the original port, including IPv6 authorities.
        if hostport.startswith("["):
            close_bracket = hostport.find("]")
            port_suffix = hostport[close_bracket + 1:] if close_bracket != -1 else ""
            replacement = (
                new_host
                if new_host.startswith("[")
                else f"[{new_host}]" if ":" in new_host else new_host
            )
        else:
            colon = hostport.rfind(":")
            if colon != -1 and hostport[colon + 1:].isdigit():
                port_suffix = hostport[colon:]
            else:
                port_suffix = ""

            replacement = new_host

        return urlunsplit((
            parts.scheme,
            prefix + replacement + port_suffix,
            parts.path,
            parts.query,
            parts.fragment,
        ))

    results = []

    for url in urls:
        parts = urlsplit(url)
        rewritten_url = url
        matched = False

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]
            action = rule["action"]
            action_value = rule.get("action_value")

            if match_type == "path_prefix":
                matches = parts.path.startswith(match_value)

            elif match_type == "host":
                matches = host_matches(parts.hostname, match_value)

            elif match_type == "query_param":
                query_names = {
                    name for name, _ in parse_qsl(
                        parts.query,
                        keep_blank_values=True
                    )
                }
                matches = match_value in query_names

            else:
                matches = False

            if not matches:
                continue

            matched = True

            if action == "block":
                rewritten_url = None

            elif action == "strip_prefix":
                path = parts.path
                if path.startswith(action_value):
                    new_path = path[len(action_value):] or "/"
                    rewritten_url = urlunsplit((
                        parts.scheme,
                        parts.netloc,
                        new_path,
                        parts.query,
                        parts.fragment,
                    ))

            elif action == "redirect_host":
                rewritten_url = replace_host(parts, action_value)

            elif action == "add_query_param":
                new_query = (
                    f"{parts.query}&{action_value}"
                    if parts.query
                    else action_value
                )
                rewritten_url = urlunsplit((
                    parts.scheme,
                    parts.netloc,
                    parts.path,
                    new_query,
                    parts.fragment,
                ))

            # Only the first matching rule is used.
            break

        results.append(rewritten_url if matched else url)

    return results
